EASTERN_DIGITS = str.maketrans("0123456789", "٠١٢٣٤٥٦٧٨٩")
POINTS_SCHEDULE = [200] * 17 + [400] * 17 + [600] * 16
DIFF_FOR = {200: "EASY", 400: "MEDIUM", 600: "HARD"}
OPT_IDS = ("a", "b", "c", "d")


def to_eastern(s: str) -> str:
    return s.translate(EASTERN_DIGITS)


def year_answers(year: int) -> list[str]:
    out: list[str] = []
    seen: set[str] = set()
    for y in range(year - 3, year + 4):
        for form in (str(y), to_eastern(str(y))):
            if form not in seen:
                seen.add(form)
                out.append(form)
    return out


def uniq(items: list[str]) -> list[str]:
    seen: set[str] = set()
    out: list[str] = []
    for x in items:
        if not x:
            continue
        key = x.strip()
        low = key.casefold()
        if low in seen:
            continue
        seen.add(low)
        out.append(key)
    return out


def mc(correct: dict[str, str], wrongs: list[dict[str, str]]) -> list[dict[str, Any]]:
    opts = [{"id": "a", "text": {"ar": correct["ar"], "en": correct["en"]}}]
    for i, w in enumerate(wrongs[:3]):
        opts.append({"id": OPT_IDS[i + 1], "text": {"ar": w["ar"], "en": w["en"]}})
    while len(opts) < 4:
        opts.append(
            {
                "id": OPT_IDS[len(opts)],
                "text": {"ar": f"خيار {len(opts)}", "en": f"Option {len(opts)}"},
            }
        )
    # Deterministic shuffle so correct isn't always first
    seed = (len(correct["en"]) * 17 + len(correct["ar"]) * 31) % 97
    rng = random.Random(seed)
    rng.shuffle(opts)
    # Re-id after shuffle
    for i, o in enumerate(opts):
        o["id"] = OPT_IDS[i]
    return opts


def build_accepted(
    a_ar: str,
    a_en: str,
    extra: list[str] | None = None,
    year: int | None = None,
) -> list[str]:
    base = [a_ar, a_en]
    if extra:
        base.extend(extra)
    if year is not None:
        base.extend(year_answers(year))
    # Also add eastern digit forms for purely numeric answers
    for item in list(base):
        if item.isdigit():
            base.append(to_eastern(item))
    return uniq(base)


def make_q(
    category_id: str,
    points: int,
    q_type: str,
    q_ar: str,
    q_en: str,
    a_ar: str,
    a_en: str,
    *,
    accepted: list[str] | None = None,
    wrongs: list[dict[str, str]] | None = None,
    hint_ar: str | None = None,
    hint_en: str | None = None,
    year: int | None = None,
) -> dict[str, Any]:
    assert q_type in ("MULTIPLE_CHOICE", "TEXT")
    assert points in (200, 400, 600)
    acc = build_accepted(a_ar, a_en, accepted, year)
    hint_ar = hint_ar or f"ابدأ بحرف: {a_ar[0]}"
    hint_en = hint_en or f"Starts with: {a_en[0]}"
    q: dict[str, Any] = {
        "categoryId": category_id,
        "points": points,
        "difficulty": DIFF_FOR[points],
        "type": q_type,
        "language": "ar",
        "questionTextAr": q_ar,
        "questionTextEn": q_en,
        "answerAr": a_ar,
        "answerEn": a_en,
        "acceptedAnswers": acc,
        "hintAr": hint_ar,
        "hintEn": hint_en,
        "optionsJson": None,
    }
    if q_type == "MULTIPLE_CHOICE":
        assert wrongs and len(wrongs) >= 3, f"MC needs 3 wrongs: {q_en}"
        q["optionsJson"] = mc({"ar": a_ar, "en": a_en}, wrongs)
    return q


def assign_points(facts: list[dict[str, Any]], category_id: str) -> list[dict[str, Any]]:
    assert len(facts) >= 50, f"{category_id} has only {len(facts)} facts"
    facts = facts[:50]
    out: list[dict[str, Any]] = []
    for i, f in enumerate(facts):
        points = POINTS_SCHEDULE[i]
        out.append(
            make_q(
                category_id,
                points,
                f["type"],
                f["qAr"],
                f["qEn"],
                f["aAr"],
                f["aEn"],
                accepted=f.get("accepted"),
                wrongs=f.get("wrongs"),
                hint_ar=f.get("hintAr"),
                hint_en=f.get("hintEn"),
                year=f.get("year"),
            )
        )
    return out


def F(
    q_ar: str,
    q_en: str,
    a_ar: str,
    a_en: str,
    *,
    mc_wrongs: list[tuple[str, str]] | None = None,
    accepted: list[str] | None = None,
    hint_ar: str | None = None,
    hint_en: str | None = None,
    year: int | None = None,
    as_text: bool = False,
) -> dict[str, Any]:
    """Compact fact builder. Provide mc_wrongs for MULTIPLE_CHOICE unless as_text=True."""
    use_mc = mc_wrongs is not None and not as_text
    d: dict[str, Any] = {
        "type": "MULTIPLE_CHOICE" if use_mc else "TEXT",
        "qAr": q_ar,
        "qEn": q_en,
        "aAr": a_ar,
        "aEn": a_en,
    }
    if accepted:
        d["accepted"] = accepted
    if hint_ar:
        d["hintAr"] = hint_ar
    if hint_en:
        d["hintEn"] = hint_en
    if year is not None:
        d["year"] = year
    if use_mc and mc_wrongs is not None:
        d["wrongs"] = [{"ar": a, "en": e} for a, e in mc_wrongs]
    return d


