BANKS = {
    "general": GENERAL,
    "history": HISTORY,
    "geography": GEOGRAPHY,
    "science": SCIENCE,
    "technology": TECHNOLOGY,
    "sports": SPORTS,
    "football": FOOTBALL,
    "movies": MOVIES,
    "tv": TV,
    "anime": ANIME,
    "music": MUSIC,
    "celebrities": CELEBRITIES,
    "arab-culture": ARAB_CULTURE,
    "islamic": ISLAMIC,
    "food": FOOD,
    "countries": COUNTRIES,
    "animals": ANIMALS,
    "brands": BRANDS,
    "gaming": GAMING,
    "cars": CARS,
    "space": SPACE,
    "literature": LITERATURE,
    "languages": LANGUAGES,
    "riddles": RIDDLES,
    "math": MATH,
    "random": RANDOM,
}


def _numeric_wrongs(n: int) -> list[dict[str, str]]:
    deltas = [1, 2, 3, 4, 5, 10, -1, -2, -3, 7, 8]
    wrongs: list[dict[str, str]] = []
    seen = {n}
    for d in deltas:
        v = n + d
        if v in seen or v < 0:
            continue
        seen.add(v)
        s = str(v)
        wrongs.append({"ar": s, "en": s})
        if len(wrongs) >= 3:
            break
    while len(wrongs) < 3:
        v = n + 10 + len(wrongs)
        s = str(v)
        wrongs.append({"ar": s, "en": s})
    return wrongs


def boost_mc_ratio(questions: list[dict[str, Any]], target_mc_frac: float = 0.60) -> list[dict[str, Any]]:
    """Convert eligible TEXT items to MC until ~60% multiple choice."""
    total = len(questions)
    target_mc = int(total * target_mc_frac)
    mc_count = sum(1 for q in questions if q["type"] == "MULTIPLE_CHOICE")
    if mc_count >= target_mc:
        return questions

    # Pass 1: numeric answers -> nearby numbers
    for q in questions:
        if mc_count >= target_mc:
            return questions
        if q["type"] != "TEXT":
            continue
        ans = q["answerEn"].strip()
        if not ans.isdigit():
            continue
        n = int(ans)
        q["type"] = "MULTIPLE_CHOICE"
        q["optionsJson"] = mc({"ar": q["answerAr"], "en": q["answerEn"]}, _numeric_wrongs(n))
        mc_count += 1

    # Pass 2: short answers -> other answers from same category as distractors
    by_cat: dict[str, list[dict[str, Any]]] = {}
    for q in questions:
        by_cat.setdefault(q["categoryId"], []).append(q)

    for q in questions:
        if mc_count >= target_mc:
            break
        if q["type"] != "TEXT":
            continue
        # Skip very long / multi-part answers (poor MC fit)
        if "/" in q["answerEn"] or len(q["answerEn"]) > 40:
            continue
        peers = [
            p
            for p in by_cat[q["categoryId"]]
            if p is not q
            and p["answerEn"].casefold() != q["answerEn"].casefold()
            and p["answerAr"] != q["answerAr"]
            and "/" not in p["answerEn"]
            and len(p["answerEn"]) <= 40
        ]
        # Stable unique wrongs
        wrongs: list[dict[str, str]] = []
        seen = {q["answerEn"].casefold()}
        for p in peers:
            key = p["answerEn"].casefold()
            if key in seen:
                continue
            seen.add(key)
            wrongs.append({"ar": p["answerAr"], "en": p["answerEn"]})
            if len(wrongs) >= 3:
                break
        if len(wrongs) < 3:
            continue
        q["type"] = "MULTIPLE_CHOICE"
        q["optionsJson"] = mc({"ar": q["answerAr"], "en": q["answerEn"]}, wrongs)
        mc_count += 1
    return questions


def build_all() -> list[dict[str, Any]]:
    all_q: list[dict[str, Any]] = []
    for cid in CATEGORY_IDS:
        facts = BANKS[cid]
        if len(facts) < 50:
            raise SystemExit(f"{cid}: only {len(facts)} facts (need 50)")
        all_q.extend(assign_points(facts, cid))
    return boost_mc_ratio(all_q)


def verify(questions: list[dict[str, Any]]) -> dict[str, int]:
    per = Counter(q["categoryId"] for q in questions)
    for cid in CATEGORY_IDS:
        assert per[cid] >= 50, f"{cid} has {per[cid]} < 50"
    for q in questions:
        assert q["points"] in (200, 400, 600), q
        assert q["difficulty"] == DIFF_FOR[q["points"]], q
        assert q["type"] in ("MULTIPLE_CHOICE", "TEXT"), q
        assert "تنويع" not in q["questionTextAr"] and "تنويع" not in q["questionTextEn"]
        assert "[" not in q["questionTextAr"] and "[" not in q["questionTextEn"], q["questionTextEn"]
        if q["type"] == "MULTIPLE_CHOICE":
            opts = q["optionsJson"]
            assert opts is not None and len(opts) == 4, q["questionTextEn"]
            for o in opts:
                assert "id" in o and "text" in o and "ar" in o["text"] and "en" in o["text"]
            texts_ar = [o["text"]["ar"] for o in opts]
            assert q["answerAr"] in texts_ar, q["questionTextEn"]
        else:
            assert q["optionsJson"] is None
        assert isinstance(q["acceptedAnswers"], list) and len(q["acceptedAnswers"]) >= 1
    return dict(per)


def main() -> None:
    questions = build_all()
    per = verify(questions)
    total = len(questions)
    mc = sum(1 for q in questions if q["type"] == "MULTIPLE_CHOICE")
    tx = total - mc

    BANK_PATH.write_text(json.dumps(questions, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    meta = {"total": total, "perCategory": {cid: per[cid] for cid in CATEGORY_IDS}}
    META_PATH.write_text(json.dumps(meta, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    print("=== Seen Jeem Question Bank ===")
    print(f"Total questions: {total}")
    print(f"MULTIPLE_CHOICE: {mc} ({100 * mc / total:.1f}%)  TEXT: {tx} ({100 * tx / total:.1f}%)")
    print("Per category:")
    for cid in CATEGORY_IDS:
        print(f"  {cid}: {per[cid]}")
    print(f"Wrote {BANK_PATH}")
    print(f"Wrote {META_PATH}")
    print("Verification: PASSED")


if __name__ == "__main__":
    main()
